    private Optional<Integer> parseInstanceIdReflectively(String instanceName) throws Exception {
        java.lang.reflect.Method method = InstanceUtils.class.getDeclaredMethod("parseInstanceId", String.class);
        method.setAccessible(true);
        return (Optional<Integer>) method.invoke(null, instanceName);
    }
